"""One-shot patch: v15.69 -> v15.70 (Round 11: quiet fan-out + playlist button).

Artist batches no longer flood the chat: no per-song "Downloaded!
Waiting for other tasks..." messages and no per-song error messages
(the artist status note tracks progress and lists unavailable songs).
The final file list is compact (one line per song with its stream
and download links), and after the batch a prompt offers to build one
playlist page from exactly this batch's uploaded songs.
"""
import ast
import base64
import py_compile
import sys

P = "kaggle_notebook.py"
s = open(P, encoding="utf-8").read()

if "v15.70" in s:
    py_compile.compile(P, doraise=True)
    print("already v15.70 - no changes")
    sys.exit(0)
if "v15.69" not in s:
    sys.exit("no v15.69 markers found - unexpected notebook")

def _dec(x):
    return base64.b64decode(x).decode("utf-8")

# -- 1. the r3 music module blob ----------------------------------------
i = s.index("WZFIX_R3_MUSIC_B64 = (")
j = s.index("\n)", i) + 2
src = base64.b64decode(
    ast.literal_eval(s[i + len("WZFIX_R3_MUSIC_B64 = "):j])
).decode("utf-8")
_old = _dec("ICAgIF9zaGFyZWQgPSB7ZiIve19mb2xkZXJ9IjogeyJ0b3RhbCI6IF9uLCAidGFza3MiOiBzZXQoKX19")  # edit1 (fan-out marker)
_new = _dec("")
if src.count(_old) != 1:
    sys.exit("r3 anchor not unique: edit1 (fan-out marker)")
src = src.replace(_old, _new)
_old = _dec("")  # edit2 (watcher)
_new = _dec("")
if src.count(_old) != 1:
    sys.exit("r3 anchor not unique: edit2 (watcher)")
src = src.replace(_old, _new)
src += _dec("")  # edit3 (playlist functions, append)
b64 = base64.b64encode(src.encode("utf-8")).decode("ascii")
chunks = [b64[k:k + 76] for k in range(0, len(b64), 76)]
block = (
    "WZFIX_R3_MUSIC_B64 = (\n"
    + "".join('    "%s"\n' % c for c in chunks)
    + ")"
)
s = s[:i] + block + s[j:]

# -- 2. the J-30 task_listener patch section -----------------------------
_j30 = _dec("")
_anchor = "    # J-24: ytsearch queries must not be mistaken"
if s.count(_anchor) != 1:
    sys.exit("J-24 anchor not unique")
s = s.replace(_anchor, _j30 + _anchor, 1)

# -- 3. the playlist callback registration -------------------------------
_ah = _dec("ICAgICAgICAgICAgICAgICcgICAgICAgIENhbGxiYWNrUXVlcnlIYW5kbGVyKHd6Zml4X2NhbmNlbF9jYiwgZmlsdGVycz1yZWdleCgiXnd6Zml4Y2FuY2VsJCIpKVxuJwogICAgICAgICAgICAgICAgJyAgICApXG4nCg==")
_ih = _dec("")
if s.count(_ah) != 1:
    sys.exit("handlers anchor not unique")
s = s.replace(_ah, _ah + _ih, 1)

# -- 4. version bump ------------------------------------------------------
n = s.count("v15.69")
s = s.replace("v15.69", "v15.70")
if "v15.70" not in s:
    sys.exit("version marker missing after patch")
py_compile.compile(P, doraise=True)
with open(P, "w", encoding="utf-8") as f:
    f.write(s)
print(f"patch OK: r11 quiet fan-out + playlist, {n} markers bumped to v15.70")
